entries[156473] = { ["name"] = "Verstärktes Feuermojo", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Erzeugt eine loagesegnete Flamme, die über große Entfernungen gesehen werden kann. (5 Sek. Abklingzeit)\n\"Man braucht nur ein ganz klein wenig...\"" }
