entries[156475] = { ["name"] = "Aggressionsformel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Macht Ben'jin den Sanftmütigen weniger sanftmütig... wenn alles klappt. (10 Sek. Abklingzeit)" }
entries[156476] = { ["name"] = "Dockarbeiterpfeife", ["text"] = "Einzigartig\nBenutzen: Benutzt die Pfeife, um schnell zur Atem von Pa'ku gebracht zu werden. (5 Sek. Abklingzeit)" }
