entries[156481] = { ["name"] = "Jin'Tikis verstärkter Fetisch", ["text"] = "Questgegenstand\n\"Jin'Tikis Fetisch ist mit der Macht des Feuers der uralten Nazmani erfüllt.\"" }
entries[156482] = { ["name"] = "Harpune der Zeth'jir", ["text"] = "Questgegenstand\n\"Scharf genug, um ein zweites Mal abgeschossen zu werden.\"" }
entries[156485] = { ["name"] = "Flasche voll Mojo", ["text"] = "Questgegenstand\n\"Riecht nach einer Mischung aus Trollfüßen und faulen Eiern. Absolut scheußlich.\"" }
entries[156486] = { ["name"] = "Sternenverfluchter Leerenschreiter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren sternenverfluchten Leerenschreiter oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser von den Schatten berührte Schreiter verkörpert die Entschlossenheit der Elfen, im Namen der Allianz die Mächte der Leere zu bändigen.\"\nErfolg:\nVerbündete Völker: Leerenelfen" }
entries[156487] = { ["name"] = "Manasäbler der Nachtgeborenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Manasäbler der Nachtgeborenen oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese anmutige Katze ist in der Lage, große Konzentrationen arkaner Energie zu wittern und wurde von den Nachtgeborenen zum Ausdruck ihres Dankes an einen bewährten Verbündeten überreicht.\"\nErfolg:\nVerbündete Völker: Nachtgeborene" }
