entries[156516] = { ["name"] = "Betäubungsstachel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Verschießt einen mit einem starken Betäubungsmittel bedeckten Stachel, der einen Klingenstacheleber für 30 Sek. in einen tiefen Schlaf versetzt. Erlittener Schaden unterbricht diesen Effekt. (3 Sek. Abklingzeit)\n\"Dieser Stachel wurde in ein kräftiges Gebräu getaucht und könnte nun selbst den stärksten Borstenrücken in Schlaf versetzen.\"" }
