entries[156524] = { ["name"] = "Titanenpanzerung", ["text"] = "Questgegenstand\n\"Diese Panzerung ist mit merkwürdigen Markierungen übersät. Vielleicht kann Titanenhüter Hezrel damit etwas anfangen.\"" }
entries[156525] = { ["name"] = "Kombüsenbankett", ["text"] = "Benutzen: Richtet ein Kombüsenbankett her, das bis zu 35 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 19231 Gesundheit und 11538 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 35 erhöht.\nVerkaufspreis:" }
entries[156526] = { ["name"] = "Üppiger Kapitänsschmaus", ["text"] = "Benutzen: Richtet einen üppigen Kapitänsschmaus her, der bis zu 35 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 38462 Gesundheit und 23077 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 46 erhöht.\nVerkaufspreis:" }
