entries[156631] = { ["name"] = "Silas' Sphäre der Transmutation", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nHebt verschiedene Kessel in Kul Tiras und Zandalar hervor und gestattet es dem Spielercharakter, mit ihnen zu interagieren.\nBenutzen: Konzentriert Euch auf die Sphäre, um sie für 1 Stunde in ein anderes Objekt zu verwandeln.\nBenötigt Alchemie von Kul Tiras\n(150)\n\"Die Oberfläche der Sphäre verändert sich ständig und zeigt verschiedene Bilder für jeweils einen Augenblick, aber nie lang genug, um sie genau zu erkennen.\"" }
entries[156632] = { ["name"] = "Silas' Transportstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde (Realzeit)\nHebt verschiedene Kessel in Kul Tiras und Zandalar hervor und gestattet es dem Spielercharakter, mit ihnen zu interagieren.\nBenutzen: Beschwört ein allsehendes Auge, das Euch unverzüglich an einen sicheren Ort in der Nähe teleportieren kann. Kann nur im Freien von Kul Tiras oder Zandalar eingesetzt werden. Bleibt 2 Min. lang bestehen. (9 Min Abklingzeit)\nBenötigt Alchemie von Kul Tiras\n(1)" }
entries[156633] = { ["name"] = "Silas' Trank des Wohlstands", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde (Realzeit)\nHebt verschiedene Kessel in Kul Tiras und Zandalar hervor und gestattet es dem Spielercharakter, mit ihnen zu interagieren.\nBenutzen: Erhöht die Chance, zusätzliche Alchemiegegenstände von Kul Tiras herzustellen. (20 Min Abklingzeit)\nBenötigt Alchemie von Kul Tiras\n(1)" }
entries[156634] = { ["name"] = "Silas' Phiole der steten Genesung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde (Realzeit)\nHebt verschiedene Kessel in Kul Tiras und Zandalar hervor und gestattet es dem Spielercharakter, mit ihnen zu interagieren.\nBenutzen: Stellt mithilfe Eurer nie endenden, immer fließenden Phiole der steten Genesung 8000 Gesundheit wieder her! (5 Min Abklingzeit)\nBenötigt Alchemie von Kul Tiras\n(1)" }
entries[156635] = { ["name"] = "Honigbeflecktes Notizbuch", ["text"] = "Einzigartig\n\"Es ist noch ziemlich klebrig und ein paar Seiten fehlen.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[156636] = { ["name"] = "Blutvertrag: Vergessenheit", ["text"] = "Benutzen: Beschwört einen Avatar der Vergessenheit, der 4 Stunden lang an Euer Seite kämpft." }
