entries[156640] = { ["name"] = "Vol'jins Unverwundbarkeitstotem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gaunah garantiert, dass dieses lang verlorene Totem des kürzlich verschiedenen Kriegshäuptlings der Horde Euch vor tödlichem Schaden schützen wird. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[156641] = { ["name"] = "Zuls Sauridenzauberschutz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gaunah behauptet, dieses Totem würde Sauriden von Euch fernhalten. Perfekt für Ladeninhaber und Reisende! (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[156642] = { ["name"] = "Rastakhans Totem der ewigen Flamme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gaunah behauptet, dass dieses Feuertotem brennt, seit Rastakhan das erste Mal auf dem Thron von Zuldazar saß, und nicht gelöscht werden kann, solange er lebt. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[156643] = { ["name"] = "Talanjis Totem der flüsternden Irrwische", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gaunah behauptet, dieses Totem sei der wertvollste Besitz von Prinzessin Talanji, mit dem sie alle Bewohner von Zuldazar ausspionieren konnte. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[156646] = { ["name"] = "Flasche mit Azerit", ["text"] = "Benutzen: Gaunah verspricht, dass dieser Trank Euch sofort stärker machen wird. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[156647] = { ["name"] = "Tasche mit \"abgelegten\" Ruhesteinen", ["text"] = "\"Auf keinen Fall gestohlen. Nein. Niemals.\"\nVerkaufspreis:" }
entries[156648] = { ["name"] = "Ernterdingsbums", ["text"] = "Questgegenstand\n\"Reichlich Dingsbumse und Kram.\"" }
entries[156649] = { ["name"] = "Zandalarisches Abbildamulett", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Erstellt ein angreifbares Abbild Eures aktuellen Ziels. (15 Min Abklingzeit)\n\"Zeigt ihnen, was Ihr wirklich von ihnen haltet.\"" }
