entries[156652] = { ["name"] = "Jahrhundertblüte", ["text"] = "\"Diese seltene Blume blüht nur einmal alle hundert Jahre. Bei den langlebigen Völkern Zuldazars sind die Blüten heiß begehrt.\"" }
