entries[156751] = { ["name"] = "Nachtbinderhandschutz", ["text"] = "Wird beim Aufheben gebunden\nHände Leder\n5 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 5.\nVerkaufspreis:" }
entries[156752] = { ["name"] = "Schädelbrecherstulpen", ["text"] = "Wird beim Aufheben gebunden\nHände Platte\n11 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 5.\n+ 4 Vielseitigkeit\nVerkaufspreis:" }
entries[156753] = { ["name"] = "Wendehandschuhe", ["text"] = "Wird beim Aufheben gebunden\nHände Stoff\n3 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure Tempowertung um + 5.\n+ 4 Vielseitigkeit\nVerkaufspreis:" }
entries[156754] = { ["name"] = "Gurgelquetscherhandschutz", ["text"] = "Wird beim Aufheben gebunden\nHände Kette\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\n+ 3 Vielseitigkeit\nVerkaufspreis:" }
entries[156755] = { ["name"] = "Tuch der Verrachgeltung", ["text"] = "Wird beim Aufheben gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nVerkaufspreis:" }
entries[156758] = { ["name"] = "Irisierende Schillerrochenhaut", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Jedes Mal, wenn ein Schillerrochen die Haut abwirft, schillert er in einem noch breiteren Lichtspektrum.\"" }
entries[156760] = { ["name"] = "Elementarer Wassertropfen", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Manchmal bleibt ein Elementar an einem Felsen oder einem scharfen Korallenstück hängen, wodurch ein kleiner Teil von ihm zurückbleibt. Versucht, ihn nicht zu verärgern.\"" }
entries[156761] = { ["name"] = "Sehr hübsche Koralle", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Absolut jeder stimmt zu: Diese Koralle ist schön anzuschauen.\"" }
entries[156762] = { ["name"] = "Echomuschel der Sirene", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Ihr könnt den durchdringenden Schrei der Sirene noch immer in dieser Muschel widerhallen hören.\"" }
entries[156763] = { ["name"] = "Rennfischflossenspitzen", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Was für ein Monster muss man sein, um einem Rennfisch die Flossenspitzen abzuschneiden? Ihr fragt Euch, ob Ihr derart abscheuliche Praktiken unterstützen sollt.\"" }
entries[156764] = { ["name"] = "Üppige Luxschuppenschuppe", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Durch ihre bloße Nähe wird ihre Opulenz nahezu greifbar.\"" }
entries[156765] = { ["name"] = "Noch immer zuckendes Tentakel", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Ihr seid Euch ziemlich sicher, dass Ihr gar nicht wissen wollt, von welcher Kreatur das stammt.\"" }
entries[156766] = { ["name"] = "Gleißende Laternenfischkugel", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Hell genug, um durch die abgrundtiefe Dunkelheit Eures Geistes zu sehen.\"" }
entries[156767] = { ["name"] = "Verkrustetes Schneckenhaus", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Die Mutter dieser Schnecke hat ihr anscheinend nie beigebracht, ihr Zimmer aufzuräumen. Was für ein Chaos!\"" }
entries[156768] = { ["name"] = "Extrem feiner Sand", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Im Prinzip ein Pulver, das aufgrund unklarer Gesetze des Meeres aber nicht als solches vermarktet wird.\"\nVerkaufspreis:" }
entries[156769] = { ["name"] = "Unzerkratztes Schildkrötenpanzerfragment", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Ihr seid Euch nicht sicher, wie lange es noch in makellosem Zustand bleiben wird, aber vermutlich nicht mehr lange, so wie es in Euren Taschen herumkullert.\"" }
entries[156770] = { ["name"] = "Extrem glitschiger Aalschleim", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Aale haben bei Meeresgeburtstagsfeiern das Monopol auf den Betrieb der Bauchrutschbahnen.\"" }
entries[156771] = { ["name"] = "Schwarze Vantuskalmartinte", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Diese Tinte ist so schwarz, dass sie sogar ihre Umgebung erkennbar zu verdunkeln scheint.\"" }
entries[156772] = { ["name"] = "Besonders scharfe Kugelfischstacheln", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Trieft immer noch vor einem starken Toxin, das Geist und Körper lähmt.\"\nVerkaufspreis:" }
entries[156773] = { ["name"] = "Versehentlich abgetrennte Seepferdflosse", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Jemand sollte wirklich etwas gegen die Rasiermesserkorallen unternehmen, die an diesen niedrigen Überhängen baumeln.\"" }
entries[156774] = { ["name"] = "Glänzende Seeschlangenschuppe", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Überraschend glatt!\"\nVerkaufspreis:" }
entries[156775] = { ["name"] = "Riesiger abgeschnittener Riesenzehnagel", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Sieht aus, als wäre er eingewachsen gewesen. Armer Meeresriese.\"" }
entries[156776] = { ["name"] = "Makruraauge", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Makrura lassen sich leicht von Hummerstroks unterscheiden, und dieses Auge gehörte unverkennbar einem Makrura. Sie sind höchst verschieden, wie jeder weiß.\"\nVerkaufspreis:" }
entries[156777] = { ["name"] = "Hummerstrokauge", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Dieses Auge stammt eindeutig von einem Hummerstrok, und nicht von einem Makrura. Der Unterschied ist offensichtlich... Nur ein Dummkopf würde die beiden verwechseln.\"" }
entries[156778] = { ["name"] = "Leitende Zitteraalflüssigkeit", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Gibt im Moment eine schwache elektrische Ladung ab, obwohl keine Energiequelle in der Nähe ist.\"\nVerkaufspreis:" }
entries[156779] = { ["name"] = "Perfekt gespitzte Schiffshalterzähne", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Die Zähne der oberen Zahnreihe eines Schiffshalters sind ungefähr 34,72% schärfer als die Zähne der unteren Reihe.\"" }
entries[156780] = { ["name"] = "Gesunder Großhaizahn", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Damit könnte man auch morgen noch kraftvoll zubeißen.\"" }
entries[156781] = { ["name"] = "Hammerhaikiemenschleim", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Vom Boden der nahe gelegenen Haiwaschanlage gekratzt.\"\nVerkaufspreis:" }
entries[156782] = { ["name"] = "Frisch abgestreifter Krabbenpanzer", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Wie es einer ganzen Krabbe gelingt, sich aus ihrem Exoskelett zu winden, ohne dass es dabei zu Bruch geht, ist Euch immer noch ein Rätsel.\"" }
entries[156783] = { ["name"] = "Wohlgenährter Knabberfisch", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Sein letzter Patient hat eindeutig noch nie von Bimsstein gehört. Sieht aus, als wäre ihm etwas übel.\"\nVerkaufspreis:" }
entries[156784] = { ["name"] = "Mantarochenstachel", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Das Ergebnis eines unglücklichen Bootsunfalls. Immerhin könnt Ihr etwas damit anfangen, oder?\"\nVerkaufspreis:" }
entries[156785] = { ["name"] = "Dreschadonflosse", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"So gut wie alle Fische scheinen die Dreschadons zu hassen. Das könnte vielleicht daran liegen, dass sie ihre Freunde verschlingen.\"" }
entries[156786] = { ["name"] = "Rasieraallarve", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\n\"Obwohl es zunächst abstoßend wirken mag, ist es bei Rasieraalen üblich, den Kümmerling jeden Geleges zu verkaufen... als Warnung für die anderen Larven.\"" }
entries[156787] = { ["name"] = "Eingefangene Kavitationsblase", ["text"] = "Wird beim Aufheben gebunden\nDauer: 30 min (Realzeit)\n\"Nach einem verheerenden Schlag des Fischkampfchampions, Eddie mit den Bowlingkugelhänden, eingefangen.\"" }
entries[156788] = { ["name"] = "Potenter Schneckenschleim", ["text"] = "Wird beim Aufheben gebunden\nDauer: 30 min (Realzeit)\n\"Irgendjemand hatte die undankbare Aufgabe, einem Bauchfüßer zu folgen und diese Flüssigkeit aufzuwischen. Der Vorteil dabei waren die kurzen Nickerchen, da man den Anschluss nur sehr schwer verlieren kann.\"\nVerkaufspreis:" }
entries[156789] = { ["name"] = "Symbiotisches Plankton", ["text"] = "Wird beim Aufheben gebunden\nDauer: 30 min (Realzeit)\n\"Ihr könnt schön leuchten, und sie dürfen Eure Haut fressen. Bei dieser Beziehung gewinnt eigentlich jeder.\"\nVerkaufspreis:" }
entries[156790] = { ["name"] = "Glitzerkiemenglitter", ["text"] = "Wird beim Aufheben gebunden\nDauer: 30 min (Realzeit)\n\"Für Zeiten, in denen Euer Äußeres das gewisse glitzernde Etwas benötigt.\"\nVerkaufspreis:" }
entries[156791] = { ["name"] = "Muschel", ["text"] = "Wird beim Aufheben gebunden\nDauer: 30 min (Realzeit)\n\"Eine gewöhnliche Muschel. Lässt sich gut stapeln.\"" }
entries[156793] = { ["name"] = "Schillernde Murlochautcreme", ["text"] = "Wird beim Aufheben gebunden\nDauer: 1 Stunde (Realzeit)\n\"Sie leuchtet, kitzelt und macht einen Murloc so schlüpfrig wie einen geölten Gnom. Ist für Nicht-Murlocs allerdings nicht sonderlich nützlich.\"" }
entries[156794] = { ["name"] = "Silithidengehirn", ["text"] = "Questgegenstand\n\"Diese schleimbedeckte Fleischmasse birgt die Geheimnisse des Nervensystems der Silithiden.\"" }
