entries[156836] = { ["name"] = "Prall gefülltes Paket", ["text"] = "Wird beim Aufheben gebunden\n\"Darauf steht nur 'Von einem Freund'.\"\n<Zum Öffnen rechtsklicken>" }
entries[156839] = { ["name"] = "Packung mit Pterrordaxleckerlis", ["text"] = "Questgegenstand\n\"Gefüllt mit einem wirren Mischmasch aus Fleisch, Knochen und etwas, das nach Keksen in Form eines Nachtelfenkopfes aussieht.\"" }
entries[156847] = { ["name"] = "Zephyriumrauchgranate", ["text"] = "Questgegenstand\nBenutzen: Schleudert eine Rauchgranate auf eine Barrikade der Bluttrolle, um sie für die Zerstörung zu markieren. (5 Sek. Abklingzeit)" }
entries[156848] = { ["name"] = "Götze von Rezan", ["text"] = "Questgegenstand\n\"Eine winzige Schnitzerei des mächtigen Teufelssaurierloas.\"" }
