entries[156852] = { ["name"] = "Ogmots Traumtagebuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Die Handschrift ist kaum lesbar und die primitiven Skizzen dazwischen sind einfach nur... verstörend.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
