entries[156861] = { ["name"] = "Schädel von Windrufer Ula'jan", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine weitere Trophäe für das Regal des Königs.\"" }
entries[156862] = { ["name"] = "Tanzfläche des großen Stylechecks", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Dekoriert die Bühne des großen Stylechecks mit Tanzdekorationen.\n\nDiese Dekorationen sind nur sichtbar, während Ihr auf der Bühne seid, und dauern während des gesamten Wettkampfs an." }
