entries[156864] = { ["name"] = "Flammen des großen Stylechecks", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Dekoriert die Bühne des großen Stylechecks mit feurigen Dekorationen.\n\nDiese Dekorationen sind nur sichtbar, während Ihr auf der Bühne seid, und dauern während des gesamten Wettkampfs an." }
entries[156865] = { ["name"] = "Amphibisches Laborgehege", ["text"] = "Questgegenstand\n\"Beobachtet Kreaturen in diesem erstaunlichen Gehege! Es funktioniert hervorragend, sowohl über als auch unter Wasser!\"" }
